dashboard.definition:
{
	"title": "SAP LogServ - Proxy Analytics",
	"description": "",
	"inputs": {
		"input_global_trp": {
			"options": {"defaultValue": "-30d@d,now", "token": "global_time"},
			"title": "Global Time Range",
			"type": "input.timerange"
		},
		"input_nav_dropdown": {
			"type": "input.dropdown",
			"title": "Navigate to Dashboard",
			"options": {
				"items": [
					{"label": "Overview", "value": "logserv_overview"},
					{"label": "DNS Analytics", "value": "logserv_dns_analytics"},
					{"label": "HANA Audit", "value": "logserv_hana_audit"},
					{"label": "HANA Trace", "value": "logserv_hana_trace"},
					{"label": "Web Dispatcher", "value": "logserv_web_dispatcher"},
					{"label": "Host Details", "value": "logserv_host_details"},
					{"label": "ABAP Security", "value": "logserv_abap_security"},
					{"label": "ABAP Operations", "value": "logserv_abap_operations"},
					{"label": "SAP Services", "value": "logserv_sap_services"},
					{"label": "Cloud Connector", "value": "logserv_cloud_connector"},
					{"label": "Linux", "value": "logserv_linux"},
					{"label": "Windows", "value": "logserv_windows"},
					{"label": "Environment Health", "value": "logserv_environment_health"}
				],
				"token": "nav_target"
			}
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_kpi_total": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_total"},
			"title": "Total Requests",
			"options": {"majorValue": "> primary | seriesByName('total') | lastPoint()", "backgroundColor": "transparent", "sparklineDisplay": "off", "trendDisplay": "off"}
		},
		"viz_kpi_bandwidth": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_bandwidth"},
			"title": "Total Bandwidth",
			"options": {"majorValue": "> primary | seriesByName('bandwidth') | lastPoint()", "backgroundColor": "transparent", "sparklineDisplay": "off", "trendDisplay": "off"}
		},
		"viz_kpi_denied": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_denied"},
			"title": "Denied Requests",
			"options": {"majorValue": "> primary | seriesByName('denied') | lastPoint()", "majorColor": "#dc4e41", "backgroundColor": "transparent", "sparklineDisplay": "off", "trendDisplay": "off"}
		},
		"viz_request_volume": {
			"type": "splunk.line",
			"dataSources": {"primary": "ds_request_volume"},
			"title": "Request Volume Over Time",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"backgroundColor": "transparent", "xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide"}
		},
		"viz_status_codes": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_status_codes"},
			"title": "Status Code Distribution",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent", "stackMode": "stacked",
				"xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide",
				"seriesColorsByField": {"2xx": "#4fa484", "3xx": "#0877a6", "4xx": "#dc4e41", "5xx": "#f1813f"}
			}
		},
		"viz_top_domains": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_top_domains"},
			"title": "Top Domains",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_top_clients": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_top_clients"},
			"title": "Top Clients",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_http_methods": {
			"type": "splunk.pie",
			"dataSources": {"primary": "ds_http_methods"},
			"title": "HTTP Methods",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"showDonutHole": true, "backgroundColor": "transparent"}
		},
		"viz_content_types": {
			"type": "splunk.pie",
			"dataSources": {"primary": "ds_content_types"},
			"title": "Content Types",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"showDonutHole": true, "backgroundColor": "transparent"}
		},
		"viz_bandwidth_timeline": {
			"type": "splunk.line",
			"dataSources": {"primary": "ds_bandwidth_timeline"},
			"title": "Bandwidth Over Time",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"backgroundColor": "transparent", "xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide"}
		},
		"viz_rect_r1l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r1r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2m": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r3l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r3r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_nav_go": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_nav_go"},
			"options": {
				"majorValue": "> primary | seriesByName('label') | lastPoint()",
				"backgroundColor": "#0877a6", "majorColor": "#ffffff",
				"sparklineDisplay": "off", "trendDisplay": "off", "majorFontSize": 14
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		}
	},
	"dataSources": {
		"ds_kpi_total": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"squid:access\" | stats count as total"}
		},
		"ds_kpi_bandwidth": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"squid:access\" | stats sum(bytes_out) as total_bytes | eval bandwidth=case(total_bytes>=1073741824, round(total_bytes/1073741824, 1).\" GB\", total_bytes>=1048576, round(total_bytes/1048576, 1).\" MB\", total_bytes>=1024, round(total_bytes/1024, 1).\" KB\", 1=1, total_bytes.\" B\")"}
		},
		"ds_kpi_denied": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"squid:access\" action=\"denied\" | stats count as denied"}
		},
		"ds_request_volume": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"squid:access\" | timechart span=1d count as Requests"}
		},
		"ds_status_codes": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"squid:access\" status=* | eval status_cat=case(status>=200 AND status<300, \"2xx\", status>=300 AND status<400, \"3xx\", status>=400 AND status<500, \"4xx\", status>=500, \"5xx\", 1=1, \"Other\") | timechart span=1d count by status_cat"}
		},
		"ds_top_domains": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"squid:access\" url_domain=* | stats count as Requests sum(bytes_out) as \"Total Bytes\" dc(src_ip) as \"Unique Clients\" by url_domain | sort -Requests | head 20 | rename url_domain as Domain"}
		},
		"ds_top_clients": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"squid:access\" src_ip=* | stats count as Requests sum(bytes_out) as \"Total Bytes\" dc(url_domain) as \"Unique Domains\" by src_ip | sort -Requests | head 20 | rename src_ip as \"Client IP\""}
		},
		"ds_http_methods": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"squid:access\" http_method=* | stats count by http_method | sort -count"}
		},
		"ds_content_types": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"squid:access\" http_content_type=* | stats count by http_content_type | sort -count | head 10"}
		},
		"ds_bandwidth_timeline": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"squid:access\" | timechart span=1d sum(bytes_out) as \"Bytes Out\""}
		},
		"ds_nav_go": {
			"type": "ds.search",
			"options": {"query": "| makeresults | eval label=\"Go >\"", "queryParameters": {"earliest": "-1m", "latest": "now"}}
		}
	},
	"layout": {
		"globalInputs": ["input_global_trp", "input_nav_dropdown"],
		"layoutDefinitions": {
			"layout_1": {
				"options": {"height": 1200, "width": 1920},
				"structure": [
					{"item": "viz_nav_go", "type": "block", "position": {"x": 1790, "y": 0, "w": 120, "h": 35}},
					{"item": "viz_kpi_total", "type": "block", "position": {"x": 10, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_kpi_bandwidth", "type": "block", "position": {"x": 320, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_kpi_denied", "type": "block", "position": {"x": 630, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_rect_r1l", "type": "block", "position": {"x": 10, "y": 150, "w": 940, "h": 340}},
					{"item": "viz_request_volume", "type": "block", "position": {"x": 20, "y": 155, "w": 920, "h": 330}},
					{"item": "viz_rect_r1r", "type": "block", "position": {"x": 960, "y": 150, "w": 950, "h": 340}},
					{"item": "viz_status_codes", "type": "block", "position": {"x": 970, "y": 155, "w": 930, "h": 330}},
					{"item": "viz_rect_r2l", "type": "block", "position": {"x": 10, "y": 505, "w": 620, "h": 340}},
					{"item": "viz_top_domains", "type": "block", "position": {"x": 20, "y": 510, "w": 600, "h": 330}},
					{"item": "viz_rect_r2m", "type": "block", "position": {"x": 640, "y": 505, "w": 640, "h": 340}},
					{"item": "viz_top_clients", "type": "block", "position": {"x": 650, "y": 510, "w": 620, "h": 330}},
					{"item": "viz_rect_r2r", "type": "block", "position": {"x": 1290, "y": 505, "w": 620, "h": 340}},
					{"item": "viz_http_methods", "type": "block", "position": {"x": 1300, "y": 510, "w": 600, "h": 330}},
					{"item": "viz_rect_r3l", "type": "block", "position": {"x": 10, "y": 860, "w": 620, "h": 330}},
					{"item": "viz_content_types", "type": "block", "position": {"x": 20, "y": 865, "w": 600, "h": 320}},
					{"item": "viz_rect_r3r", "type": "block", "position": {"x": 640, "y": 860, "w": 1270, "h": 330}},
					{"item": "viz_bandwidth_timeline", "type": "block", "position": {"x": 650, "y": 865, "w": 1250, "h": 320}}
				],
				"type": "absolute"
			}
		},
		"options": {},
		"tabs": {"items": [{"label": "New tab", "layoutId": "layout_1"}]}
	}
}
